{{ assert_case_vars() }}
with business as (select
    CAST(f.tenant_id AS String) AS `tenant_id`,
    CAST(f.opportunity_key AS String) AS `opportunity_key`,
    CAST(f.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(f.company_key AS Nullable(String)) AS `company_key`,
    CAST(f.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(f.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_name AS Nullable(String)) AS `company_name`,
    CAST(f.period_key AS String) AS `period_key`,
    CAST(f.visit_key AS Nullable(String)) AS `visit_key`,
    CAST(f.valid_from_at AS DateTime64(3, 'UTC')) AS `valid_from_at`,
    CAST(f.valid_to_at AS Nullable(DateTime64(3, 'UTC'))) AS `valid_to_at`,
    CAST(f.created_at AS Nullable(DateTime64(3, 'UTC'))) AS `created_at`,
    CAST(f.stage_id AS Nullable(Int64)) AS `stage_id`,
    CAST(f.stage_key AS Nullable(String)) AS `stage_key`,
    CAST(f.stage_version_key AS Nullable(String)) AS `stage_version_key`,
    CAST(st.stage_label AS Nullable(String)) AS `stage_label`,
    CAST(f.is_open AS Nullable(Bool)) AS `is_open`,
    CAST(if(f.stage_version_key is not null,f.stage_id=24,NULL) AS Nullable(Bool)) AS `is_demo_stage`,
    CAST(f.stage_entered_at AS Nullable(DateTime64(3, 'UTC'))) AS `stage_entered_at`,
    CAST(f.expected_close_at AS Nullable(DateTime64(3, 'UTC'))) AS `expected_close_at`,
    CAST(f.pipeline_amount AS Nullable(Decimal(38,4))) AS `pipeline_amount`,
    CAST(f.amount_basis AS Nullable(String)) AS `amount_basis`,
    CAST(f.currency_code AS Nullable(String)) AS `currency_code`,
    CAST(f.signature_probability AS Nullable(Decimal(18,8))) AS `signature_probability`,
    CAST(f.weighted_pipeline_amount AS Nullable(Decimal(38,4))) AS `weighted_pipeline_amount`,
    CAST(false AS Bool) AS `is_amount_calculable`,
    CAST(f.signature_probability is not null AS Bool) AS `is_probability_calculable`,
    CAST(f.stage_entered_at is null AS Bool) AS `is_left_censored`,
    CAST(f.coverage_start_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_start_at`,
    CAST(f.coverage_end_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_end_at`,
    CAST(f.is_history_complete AS Nullable(Bool)) AS `is_history_complete`,
    CAST(f.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(f.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(f.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(ty.sale_type_label AS Nullable(String)) AS `sale_type_label`,
    CAST(f.acquisition_channel_key AS Nullable(String)) AS `channel_key`,
    CAST(f.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(ch.channel_label AS Nullable(String)) AS `channel_label`,
    CAST(f.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(f.is_channel_calculable AS Bool) AS `is_channel_calculable`,
    CAST(f.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(f.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(em.employee_display_name AS Nullable(String)) AS `employee_display_name`,
    CAST(f.team_key AS Nullable(String)) AS `team_key`,
    CAST(f.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(tm.team_name AS Nullable(String)) AS `team_name`,
    CAST(f.is_team_calculable AS Bool) AS `is_team_calculable`,
    CAST(f.calculation_status AS String) AS `calculation_status`,
    CAST(f.status_reason AS Nullable(String)) AS `status_reason`
from {{ ref('fct_opportunity_period') }} f left join {{ ref('dim_company') }} co on f.model_run_id=co.model_run_id and f.company_version_key=co.company_version_key left join {{ ref('dim_stage') }} st on f.model_run_id=st.model_run_id and f.stage_version_key=st.stage_version_key left join {{ ref('dim_sale_type') }} ty on f.model_run_id=ty.model_run_id and f.sale_type_version_key=ty.sale_type_version_key left join {{ ref('dim_channel') }} ch on f.model_run_id=ch.model_run_id and f.channel_version_key=ch.channel_version_key left join {{ ref('dim_employee') }} em on f.model_run_id=em.model_run_id and f.employee_version_key=em.employee_version_key left join {{ ref('dim_team') }} tm on f.model_run_id=tm.model_run_id and f.team_version_key=tm.team_version_key where f.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}),
